    SeedSection(
      stableId: 'ch13_sec_03',
      orderIndex: 3,
      titleUrdu: '3۔ سیدہ عائشہ کا صبرِ جمیل، سورۃ النور میں براءت اور ابوبکر و مسطح کا سبق',
      paragraphs: [
        SeedParagraph(
          stableId: 'ch13_p_02e',
          orderIndex: 1,
          isDailyEligible: false,
          plainText:
              'ایک ماہ وحی رکی رہنے کے بعد رسول اللہ ﷺ خود حضرت ابوبکر کے گھر تشریف لائے اور سیدہ عائشہ کے پاس بیٹھ کر تشہد کے بعد نہایت نرمی سے فرمایا: «اے عائشہ! تمہارے بارے میں یہ باتیں مجھ تک پہنچی ہیں؛ اگر تم بے گناہ ہو تو عنقریب اللہ تمہیں بری فرما دے گا، اور اگر کوئی لغزش ہو گئی ہے تو اللہ سے معافی مانگو اور توبہ کرو، کیونکہ جب بندہ اعتراف کر کے توبہ کرتا ہے تو اللہ اس کی توبہ قبول فرما لیتا ہے۔» یہ سن کر سیدہ عائشہ کے آنسو خشک ہو گئے؛ انہوں نے والد اور والدہ سے کہا کہ آپ کی طرف سے جواب دیں مگر دونوں کی زبان گنگ تھی، تب انیس سالہ سیدہ عائشہ نے خود نہایت وقار سے فرمایا: «واللہ! تم نے یہ بات سن لی ہے اور تمہارے دلوں میں بس گئی ہے؛ اگر میں کہوں میں بے گناہ ہوں—اور اللہ جانتا ہے میں بے گناہ ہوں—تو تم یقین نہ کرو گے، اور اگر کسی ایسی بات کا اقرار کر لوں جس سے اللہ مجھے پاک جانتا ہے تو تم مان لو گے؛ چنانچہ میرے پاس یوسف علیہ السلام کے والد (حضرت یعقوب) کے قول کے سوا کچھ نہیں: فَصَبْرٌ جَمِيلٌ ۖ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ!» یہ کہہ کر وہ کروٹ پھیر کر بستر پر لیٹ گئیں، اور عین اسی وقت آپ ﷺ اپنی نشست سے اٹھے بھی نہ تھے کہ وحی کی کیفیت طاری ہو گئی، سخت سردی میں بھی پیشانی سے موتیوں جیسے پسینے کے قطرے ٹپکنے لگے؛ جب وحی ختم ہوئی تو آپ ﷺ مسکراتے ہوئے اٹھے اور پہلا جملہ فرمایا: «أَبْشِرِي يَا عَائِشَةُ، أَمَّا اللَّهُ فَقَدْ بَرَّأَكِ!» (اے عائشہ خوش ہو جاؤ، اللہ نے تمہیں بری فرما دیا!)۔ سورۃ النور کی آیات 11 تا 22 نازل ہوئیں؛ مسطح، حسان اور حمنہ پر حدِ قذف (اسی کوڑے) جاری ہوئی، اور حضرت ابوبکر نے قسم کھا لی کہ اب مسطح کی مدد نہیں کریں گے تو اللہ نے نازل فرمایا: «أَلَا تُحِبُّونَ أَن يَغْفِرَ اللَّهُ لَكُمْ» (کیا تم پسند نہیں کرتے کہ اللہ تمہیں بخش دے؟)—فوراً حضرت ابوبکر بول اٹھے: «بَلَىٰ وَاللَّهِ يَا رَبَّنَا، نُحِبُّ أَن تَغْفِرَ لَنَا!» اور مسطح کا وظیفہ ہمیشہ کے لیے بحال فرما دیا۔',
          claims: [
            SeedClaim(
              stableId: 'ch13_c_07',
              order: 1,
              status: ReliabilityStatus.confirmed,
              text:
                  'ایک ماہ وحی رکی رہنے کے بعد رسول اللہ ﷺ خود حضرت ابوبکر کے گھر تشریف لائے اور سیدہ عائشہ کے پاس بیٹھ کر تشہد کے بعد نہایت نرمی سے فرمایا: «اے عائشہ! تمہارے بارے میں یہ باتیں مجھ تک پہنچی ہیں؛ اگر تم بے گناہ ہو تو عنقریب اللہ تمہیں بری فرما دے گا، اور اگر کوئی لغزش ہو گئی ہے تو اللہ سے معافی مانگو اور توبہ کرو، کیونکہ جب بندہ اعتراف کر کے توبہ کرتا ہے تو اللہ اس کی توبہ قبول فرما لیتا ہے۔» یہ سن کر سیدہ عائشہ کے آنسو خشک ہو گئے؛ انہوں نے والد اور والدہ سے کہا کہ آپ کی طرف سے جواب دیں مگر دونوں کی زبان گنگ تھی، تب انیس سالہ سیدہ عائشہ نے خود نہایت وقار سے فرمایا: «واللہ! تم نے یہ بات سن لی ہے اور تمہارے دلوں میں بس گئی ہے؛ اگر میں کہوں میں بے گناہ ہوں—اور اللہ جانتا ہے میں بے گناہ ہوں—تو تم یقین نہ کرو گے، اور اگر کسی ایسی بات کا اقرار کر لوں جس سے اللہ مجھے پاک جانتا ہے تو تم مان لو گے؛ چنانچہ میرے پاس یوسف علیہ السلام کے والد (حضرت یعقوب) کے قول کے سوا کچھ نہیں: فَصَبْرٌ جَمِيلٌ ۖ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ!» یہ کہہ کر وہ کروٹ پھیر کر بستر پر لیٹ گئیں، اور عین اسی وقت آپ ﷺ اپنی نشست سے اٹھے بھی نہ تھے کہ وحی کی کیفیت طاری ہو گئی، سخت سردی میں بھی پیشانی سے موتیوں جیسے پسینے کے قطرے ٹپکنے لگے؛ جب وحی ختم ہوئی تو آپ ﷺ مسکراتے ہوئے اٹھے اور پہلا جملہ فرمایا: «أَبْشِرِي يَا عَائِشَةُ، أَمَّا اللَّهُ فَقَدْ بَرَّأَكِ!» (اے عائشہ خوش ہو جاؤ، اللہ نے تمہیں بری فرما دیا!)۔ سورۃ النور کی آیات 11 تا 22 نازل ہوئیں؛ مسطح، حسان اور حمنہ پر حدِ قذف (اسی کوڑے) جاری ہوئی، اور حضرت ابوبکر نے قسم کھا لی کہ اب مسطح کی مدد نہیں کریں گے تو اللہ نے نازل فرمایا: «أَلَا تُحِبُّونَ أَن يَغْفِرَ اللَّهُ لَكُمْ» (کیا تم پسند نہیں کرتے کہ اللہ تمہیں بخش دے؟)—فوراً حضرت ابوبکر بول اٹھے: «بَلَىٰ وَاللَّهِ يَا رَبَّنَا، نُحِبُّ أَن تَغْفِرَ لَنَا!» اور مسطح کا وظیفہ ہمیشہ کے لیے بحال فرما دیا۔',
